input.command:
cd "/Users/daniel/Documents/proyectos_odoo/odoo_19/custom_addons/LYD_LATAM_prueba_tecnica/prueba_tecnica"
mkdir -p .claude/hooks
cat > .claude/hooks/sync_claude_logs.sh <<'EOF'
#!/bin/bash
# Copia los registros (transcripts) de Claude Code de ESTE proyecto a ./claude_logs
# Se ejecuta solo desde los hooks de .claude/settings.json de esta carpeta.
INPUT=$(cat)
TRANSCRIPT=$(echo "$INPUT" | jq -r '.transcript_path // empty')
PROJECT_DIR="${CLAUDE_PROJECT_DIR:-$(pwd)}"
[ -z "$TRANSCRIPT" ] && exit 0
SRC_DIR=$(dirname "$TRANSCRIPT")
[ -d "$SRC_DIR" ] || exit 0
mkdir -p "$PROJECT_DIR/claude_logs"
# Sin --delete: los registros se conservan aunque Claude limpie los originales
rsync -a "$SRC_DIR/" "$PROJECT_DIR/claude_logs/" >/dev/null 2>&1
exit 0
EOF
chmod +x .claude/hooks/sync_claude_logs.sh
cat > .claude/settings.json <<'EOF'
{
  "hooks": {
    "Stop": [
      { "hooks": [ { "type": "command", "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/sync_claude_logs.sh" } ] }
    ],
    "SubagentStop": [
      { "hooks": [ { "type": "command", "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/sync_claude_logs.sh" } ] }
    ],
    "PreCompact": [
      { "hooks": [ { "type": "command", "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/sync_claude_logs.sh" } ] }
    ],
    "SessionEnd": [
      { "hooks": [ { "type": "command", "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/sync_claude_logs.sh" } ] }
    ]
  }
}
EOF
jq . .claude/settings.json >/dev/null && echo json-ok
# Prueba manual + sincronización inicial
echo '{"transcript_path":"'"$HOME"'/.claude-personal/projects/-Users-daniel-Documents-proyectos-odoo-odoo-19-custom-addons-LYD-LATAM-prueba-tecnica-prueba-tecnica/1ab483db-8e9b-45b2-b8a1-ec20d58d4d80.jsonl"}' | CLAUDE_PROJECT_DIR="$PWD" .claude/hooks/sync_claude_logs.sh
ls -la claude_logs

